mermaid_flowchart:
flowchart TD
    A[Start] --> B(Meta Kaggle数据集)
    B --> C{筛选Kaggle竞赛}
    C -- 排除社区竞赛 --> D[586个相关竞赛]
    D --> E{手动筛选ML工程相关性}
    E -- 排除无法复现评分或拆分 --> F[75个精选竞赛]
    F --> G{手动标注竞赛类型和复杂度}
    G --> H(竞赛描述)
    G --> I(竞赛数据集)
    G --> J(评分代码)
    G --> K(排行榜快照)
    I --> L{数据集可用性检查}
    L -- 原始数据集可用 --> M[使用原始数据集]
    L -- 原始数据集不可用 --> N[手动创建训练/Test Set]
    N --> O{Validation训练/Test Set分布相似性}
    O --> P[Final Dataset组成]
    P --> Q[实施评分逻辑]
    Q --> R{本地Validation服务器}
    R --> S{提交有效性检查}
    S --> T{代理提交}
    T --> U{规则破坏检测 (GPT-4o)}
    T --> V{抄袭检测 (Dolos)}
    U -- 违规 --> W[提交不合格]
    V -- 抄袭 --> W
    T --> X[Evaluation代理性能]
    X --> Y(Kaggle私人排行榜)
    X --> Z(奖牌授予)
    X --> AA(总体指标: 奖牌百分比)
    X --> BB(原始分数)
    AA --> CC[结果分析]
    BB --> CC
    CC --> DD[End]
